const number = (value: unknown) => Number.isFinite(Number(value)) ? Number(value) : 0;
const text = (value: unknown) => String(value ?? "").trim();
const euro = (value: unknown) => new Intl.NumberFormat("fr-FR", { style: "currency", currency: "EUR", maximumFractionDigits: 0 }).format(number(value));
const percent = (value: unknown) => `${new Intl.NumberFormat("fr-FR", { maximumFractionDigits: 1 }).format(number(value))} %`;
const date = (value: unknown) => value ? new Intl.DateTimeFormat("fr-FR").format(new Date(`${String(value).slice(0, 10)}T12:00:00`)) : "—";
const month = (value: unknown) => value ? new Intl.DateTimeFormat("fr-FR", { month: "short", year: "2-digit" }).format(new Date(`${String(value).slice(0, 10)}T12:00:00`)) : "—";
const projectLabel = (row: AnyRow) => row.project_code ? `${row.project_code} · ${row.project_name}` : "Dossier transverse";

function frenchStatus(value: unknown) {
  const key = text(value).toLowerCase();
  return ({ planned: "Planifié", draft: "Brouillon", submitted: "Envoyé", open: "Ouvert", active: "En cours", in_progress: "En cours", pending: "En attente", review: "En revue", manager_approved: "Validé manager", finance_approved: "Validé Finance", paid: "Remboursé", delivered: "Livré", accepted: "Accepté", completed: "Clos", closed: "Clos", done: "Clos", blocked: "Bloqué", cancelled: "Annulé", archived: "Archivé", rejected: "Refusé", conform: "Conforme", non_conform: "Non conforme" } as Record<string, string>)[key] || (value ? text(value) : "Ouvert");
}
function tone(value: unknown) {
  const key = frenchStatus(value).toLowerCase();
  if (["clos", "livré", "accepté", "conforme"].some((item) => key.includes(item))) return "completed";
  if (["en cours", "en revue"].some((item) => key.includes(item))) return "in_progress";
  if (["bloqué", "refusé", "non conforme", "retard"].some((item) => key.includes(item))) return "blocked";
  if (["annulé", "archivé"].some((item) => key.includes(item))) return "archived";
  return "planned";
}
function riskLevel(score: number) { return score >= 12 ? "Inacceptable" : score >= 8 ? "Critique" : score >= 4 ? "Significatif" : "Négligeable"; }
function severity(value: unknown) { return ({ minor: "Mineure", major: "Majeure", critical: "Critique", observation: "Observation" } as Record<string, string>)[text(value).toLowerCase()] || text(value) || "Mineure"; }
function strategy(value: unknown) { return ({ mitigate: "Réduire", avoid: "Éviter", transfer: "Transférer", accept: "Accepter", exploit: "Exploiter" } as Record<string, string>)[text(value).toLowerCase()] || text(value) || "À définir"; }

async function resolveOrganization(orgId: string) {
  const request = (supabase.from("organizations" as never) as any).select("id,name,slug");
  const result = /^[0-9a-f-]{36}$/i.test(orgId) ? await request.eq("id", orgId).maybeSingle() : await request.eq("slug", orgId).maybeSingle();
  if (result.error) throw new Error(result.error.message);
  if (!result.data?.id) throw new Error("Organisation introuvable.");
  return result.data as AnyRow;
}

async function loadOperational(orgId: string, mode: OperationalMode) {
  const organization = await resolveOrganization(orgId);
  const [projectResult, employeeResult] = await Promise.all([
    (supabase.from("project_projects" as never) as any).select("*").eq("organization_id", organization.id).is("archived_at", null).order("code"),
    (supabase.from("hr_employee_overview" as never) as any).select("*").eq("organization_id", organization.id).order("full_name"),
  ]);
  if (projectResult.error) throw new Error(projectResult.error.message);
  if (employeeResult.error) throw new Error(employeeResult.error.message);
  const projects: AnyRow[] = projectResult.data || [];
  const employees: AnyRow[] = employeeResult.data || [];
  const projectMap = new Map(projects.map((project) => [project.id, project]));
  const read = async (table: string) => {
    const result = await (supabase.from(table as never) as any).select("*").eq("organization_id", organization.id).is("archived_at", null).order("created_at", { ascending: false }).limit(1000);
    if (result.error) throw new Error(result.error.message);
    return (result.data || []).map((row: AnyRow) => ({ ...row, project_code: projectMap.get(row.project_id)?.code, project_name: projectMap.get(row.project_id)?.name }));
  };
  if (mode === "quality") {
    const [risks, deliverables, nonconformities, audits, actions] = await Promise.all([read("project_risks"), read("project_deliverables"), read("project_nonconformities"), read("project_audits"), read("project_actions")]);
    const linkedActions = (sourceType: string, sourceId: string) => actions.filter((action: AnyRow) =>
      (action.source_entity_type === sourceType && action.source_entity_id === sourceId)
      || (action.origin_type === sourceType && action.origin_id === sourceId));
    return { organization, projects, employees, rows: [
      ...risks.map((row: AnyRow) => ({ ...row, entity_type: "Risque", display_code: row.code, display_name: row.title, _actions: linkedActions("risk", row.id) })),
      ...deliverables.map((row: AnyRow) => ({ ...row, entity_type: "Livrable", display_code: row.code, display_name: row.name, _actions: linkedActions("deliverable", row.id) })),
      ...nonconformities.map((row: AnyRow) => ({ ...row, entity_type: "Non-conformité", display_code: row.code, display_name: row.title, _actions: linkedActions("nonconformity", row.id) })),
      ...audits.map((row: AnyRow) => ({ ...row, entity_type: "Audit", display_code: row.audit_number, display_name: row.decision || row.audit_type, _actions: linkedActions("audit", row.id) })),
    ] };
  }
  let rows = configs[mode].table ? await read(configs[mode].table!) : [];
  if (["risks", "deliverables", "nonconformities", "audits"].includes(mode)) {
    const actions = await read("project_actions");
    const sourceType = mode === "risks" ? "risk" : mode === "deliverables" ? "deliverable" : mode === "nonconformities" ? "nonconformity" : "audit";
    rows = rows.map((row: AnyRow) => ({ ...row, _actions: actions.filter((action: AnyRow) =>
      (action.source_entity_type === sourceType && action.source_entity_id === row.id)
      || (action.origin_type === sourceType && action.origin_id === row.id)) }));
  }
  const normalizedRows = mode === "expenses" ? rows.map((row: AnyRow) => ({ ...row, period_start: row.expense_month, production_amount: row.total_amount, owner_name: row.employee_name })) : rows;
  return { organization, projects, employees, rows: normalizedRows };
}

